-- ROCK9086 pass 16 (generated by gen_021.py): rows production logged under Fluid verification 2026-11-03..11-23.
-- Same output on DotLiquid, except the two BEHAVIOUR CHANGE rules below:
--   string-vs-bool (Block 2350 FormattedOutput, Camp Financial Aid Report page 1207): `isPublic == true` on a
--     RawValue string; Fluid shows non-public campuses. Compare to 'True' (the pass-15 fix, LavaProbe B1/B2).
--   backslash-n (WorkflowActionType 5302 / 5774 "Replace Newline Characters"): `Replace:'\n',newline` leaves a
--     visible \n in the SMS reply on Fluid. Capture the two characters and replace that (LavaProbe N1/N2).
--   unbalanced-paren (Block 1186 FormattedOutput, Serve at Christmas page 672): `{% if (campus.ShortCode == '920' %}`.
--   when-and (Block 4501 LavaTemplate, Home Groups page 1985): `when null and meetingType == ''` -> `when null`.
--   nested-comment (HtmlContent 4309, Never Going Back share-ables page 2464): inner comment tags dropped.
-- BEHAVIOUR CHANGE on DotLiquid:
--   parens (ReportField 67079 / 67094, report 1521 Can Work with Minors By Campus, page 1147): parentheses in
--     `assign` and `if`. DotLiquid read `(a or b)` as `a` alone and ignored a filter inside `if`. The conditions now
--     do what the template says: grace period is 1-60 days left, attendance compares 186 days (as in report 1522).
--   filter-in-if (HtmlContent 999, Take Away For Ferrari breadcrumbs page 1537): `{% if item | Attribute:'Slug' ==
--     storySlug %}` is always true on DotLiquid, so every story title printed. Now only the matching story prints.
-- Guarded REPLACE per row, @DryRun = 1 rolls back, the live run is all-or-nothing, one backup per row to
-- dbo._ROCK9086_LavaBackup, rows absent from the target database log -1. Clear the Rock cache after.
SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
DECLARE @DryRun bit = 1;
DECLARE @log TABLE (Tbl sysname, Id int, FixRule varchar(40), [Rows] int);
DECLARE @avkeys TABLE (Id int, AttributeId int, EntityId int);
INSERT @avkeys VALUES (2453438, 1201, 1186), (4517348, 1201, 2350), (55093101, 81470, 4501), (77085686, 17501, 5302), (79074431, 17501, 5774);
BEGIN TRAN;

IF OBJECT_ID('dbo._ROCK9086_LavaBackup') IS NULL
    CREATE TABLE dbo._ROCK9086_LavaBackup (Tbl sysname NOT NULL, Id int NOT NULL, Col sysname NOT NULL, OldValue nvarchar(max) NULL, BackedUpAt datetime NOT NULL DEFAULT GETDATE());

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'ReportField', x.[Id], 'Selection', x.[Selection] FROM [ReportField] x WHERE x.[Id] = 67079
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'ReportField' AND b.Id = x.[Id] AND b.Col = 'Selection');
UPDATE [ReportField] SET [Selection] = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE([Selection], N'{% assign add18years = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) %}', N'{% assign add18years = BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' %}'), N'{% assign add60days = (add18years| DateAdd:60,''d'' | Date:''M/d/yyyy'' ) %}', N'{% assign add60days = add18years | DateAdd:60,''d'' | Date:''M/d/yyyy'' %}'), N'{% assign DaysSinceBday = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) | DateDiff: ''Now'',''d'' %}', N'{% assign DaysSinceBday = BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' | DateDiff: ''Now'',''d'' %}'), N'{% assign daysuntil= (add60days ) | DaysUntil %}', N'{% assign daysuntil = add60days | DaysUntil %}'), N'{% if  Age == 18 and (daysuntil >=1 or daysuntil <=60)   %}', N'{% if Age == 18 and daysuntil >= 1 and daysuntil <= 60 %}')
WHERE [Id] = 67079
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign add18years = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) %}', N''))) / DATALENGTH(N'{% assign add18years = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign add60days = (add18years| DateAdd:60,''d'' | Date:''M/d/yyyy'' ) %}', N''))) / DATALENGTH(N'{% assign add60days = (add18years| DateAdd:60,''d'' | Date:''M/d/yyyy'' ) %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign DaysSinceBday = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) | DateDiff: ''Now'',''d'' %}', N''))) / DATALENGTH(N'{% assign DaysSinceBday = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) | DateDiff: ''Now'',''d'' %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign daysuntil= (add60days ) | DaysUntil %}', N''))) / DATALENGTH(N'{% assign daysuntil= (add60days ) | DaysUntil %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if  Age == 18 and (daysuntil >=1 or daysuntil <=60)   %}', N''))) / DATALENGTH(N'{% if  Age == 18 and (daysuntil >=1 or daysuntil <=60)   %}') = 1;
INSERT @log VALUES ('ReportField', 67079, 'parens', @@ROWCOUNT);

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'ReportField', x.[Id], 'Selection', x.[Selection] FROM [ReportField] x WHERE x.[Id] = 67094
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'ReportField' AND b.Id = x.[Id] AND b.Col = 'Selection');
UPDATE [ReportField] SET [Selection] = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE([Selection], N'{% assign add18years = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) %}', N'{% assign add18years = BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' %}'), N'{% assign add60days = (add18years| DateAdd:60,''d'' | Date:''M/d/yyyy'' ) %}', N'{% assign add60days = add18years | DateAdd:60,''d'' | Date:''M/d/yyyy'' %}'), N'{% assign DaysSinceBday = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) | DateDiff: ''Now'',''d'' %}', N'{% assign DaysSinceBday = BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' | DateDiff: ''Now'',''d'' %}'), N'{% assign daysuntil= (add60days ) | DaysUntil %}', N'{% assign daysuntil = add60days | DaysUntil %}'), N'{% if (daysuntil < 0 or daysuntil > 60) %}', N'{% if daysuntil < 0 %}'), N'{% if (CriminalCheckStatus == ''Approved'') or (CriminalCheckStatus == ''Reapproved'') %}', N'{% if CriminalCheckStatus == ''Approved'' or CriminalCheckStatus == ''Reapproved'' %}'), N'{% if  Attendance1stVerifiedDate| Date:''M/d/yyyy'' | DateDiff:''Now'',''d'' > 186 %}', N'{% assign daysSinceFirstAttend = Attendance1stVerifiedDate | DateDiff:''Now'',''d'' %}{% if daysSinceFirstAttend > 186 %}'), N'{% if (AgeClassification == ''Child'') or (daysuntil >= 1 or daysuntil <= 60) %}', N'{% if AgeClassification == ''Child'' or daysuntil >= 1 and daysuntil <= 60 %}')
WHERE [Id] = 67094
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign add18years = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) %}', N''))) / DATALENGTH(N'{% assign add18years = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign add60days = (add18years| DateAdd:60,''d'' | Date:''M/d/yyyy'' ) %}', N''))) / DATALENGTH(N'{% assign add60days = (add18years| DateAdd:60,''d'' | Date:''M/d/yyyy'' ) %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign DaysSinceBday = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) | DateDiff: ''Now'',''d'' %}', N''))) / DATALENGTH(N'{% assign DaysSinceBday = (BirthDate | DateAdd:18,''y'' | Date:''M/d/yyyy'' ) | DateDiff: ''Now'',''d'' %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% assign daysuntil= (add60days ) | DaysUntil %}', N''))) / DATALENGTH(N'{% assign daysuntil= (add60days ) | DaysUntil %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if (daysuntil < 0 or daysuntil > 60) %}', N''))) / DATALENGTH(N'{% if (daysuntil < 0 or daysuntil > 60) %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if (CriminalCheckStatus == ''Approved'') or (CriminalCheckStatus == ''Reapproved'') %}', N''))) / DATALENGTH(N'{% if (CriminalCheckStatus == ''Approved'') or (CriminalCheckStatus == ''Reapproved'') %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if  Attendance1stVerifiedDate| Date:''M/d/yyyy'' | DateDiff:''Now'',''d'' > 186 %}', N''))) / DATALENGTH(N'{% if  Attendance1stVerifiedDate| Date:''M/d/yyyy'' | DateDiff:''Now'',''d'' > 186 %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if (AgeClassification == ''Child'') or (daysuntil >= 1 or daysuntil <= 60) %}', N''))) / DATALENGTH(N'{% if (AgeClassification == ''Child'') or (daysuntil >= 1 or daysuntil <= 60) %}') = 1;
INSERT @log VALUES ('ReportField', 67094, 'parens', @@ROWCOUNT);

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'AttributeValue', x.[Id], 'Value', x.[Value] FROM [AttributeValue] x WHERE x.[Id] = 4517348 AND x.[AttributeId] = 1201 AND x.[EntityId] = 2350
